static const char*TAG="FACTORY_V1";static uint16_t frame[W*H];static esp_lcd_panel_handle_t panel;static int glitch_count=0;
static inline uint16_t rgb(uint8_t r,uint8_t g,uint8_t b){uint16_t c=((r&0xF8)<<8)|((g&0xFC)<<3)|(b>>3);return(c>>8)|(c<<8);}static void rect(int x,int y,int w,int h,uint16_t c){for(int yy=y;yy<y+h&&yy<H;yy++)for(int xx=x;xx<x+w&&xx<W;xx++)if(xx>=0&&yy>=0)frame[yy*W+xx]=c;}
static const uint8_t SP[5]={0},DA[5]={8,8,8,8,8},DT[5]={0,0x60,0x60,0,0},DP[5]={8,8,0x3e,8,8},DH[5]={0x14,0x7f,0x14,0x7f,0x14},D0[5]={0x3e,0x51,0x49,0x45,0x3e},D1[5]={0,0x42,0x7f,0x40,0},D2[5]={0x42,0x61,0x51,0x49,0x46},D3[5]={0x21,0x41,0x45,0x4b,0x31},D4[5]={0x18,0x14,0x12,0x7f,0x10},D5[5]={0x27,0x45,0x45,0x45,0x39},D6[5]={0x3c,0x4a,0x49,0x49,0x30},D7[5]={1,0x71,9,5,3},D8[5]={0x36,0x49,0x49,0x49,0x36},D9[5]={6,0x49,0x49,0x29,0x1e};
static const uint8_t A[5]={0x7e,0x11,0x11,0x11,0x7e},B[5]={0x7f,0x49,0x49,0x49,0x36},C[5]={0x3e,0x41,0x41,0x41,0x22},D[5]={0x7f,0x41,0x41,0x22,0x1c},E[5]={0x7f,0x49,0x49,0x49,0x41},F[5]={0x7f,9,9,9,1},G[5]={0x3e,0x41,0x49,0x49,0x7a},HH[5]={0x7f,8,8,8,0x7f},I[5]={0,0x41,0x7f,0x41,0},J[5]={0x20,0x40,0x41,0x3f,1},K[5]={0x7f,8,0x14,0x22,0x41},L[5]={0x7f,0x40,0x40,0x40,0x40},M[5]={0x7f,2,0x0c,2,0x7f},N[5]={0x7f,4,8,0x10,0x7f},O[5]={0x3e,0x41,0x41,0x41,0x3e},P[5]={0x7f,9,9,9,6},R[5]={0x7f,9,0x19,0x29,0x46},S[5]={0x46,0x49,0x49,0x49,0x31},T[5]={1,1,0x7f,1,1},U[5]={0x3f,0x40,0x40,0x40,0x3f},V[5]={0x1f,0x20,0x40,0x20,0x1f},WW[5]={0x3f,0x40,0x38,0x40,0x3f},X[5]={0x63,0x14,8,0x14,0x63},Y[5]={7,8,0x70,8,7},Z[5]={0x61,0x51,0x49,0x45,0x43};
static const uint8_t*glyph(char c){if(c>='0'&&c<='9'){static const uint8_t*q[]={D0,D1,D2,D3,D4,D5,D6,D7,D8,D9};return q[c-'0'];}switch(c){case'-':return DA;case'.':return DT;case'+':return DP;case'#':return DH;case'A':return A;case'B':return B;case'C':return C;case'D':return D;case'E':return E;case'F':return F;case'G':return G;case'H':return HH;case'I':return I;case'J':return J;case'K':return K;case'L':return L;case'M':return M;case'N':return N;case'O':return O;case'P':return P;case'R':return R;case'S':return S;case'T':return T;case'U':return U;case'V':return V;case'W':return WW;case'X':return X;case'Y':return Y;case'Z':return Z;default:return SP;}}
static void text(int x,int y,const char*s,int z,uint16_t c){while(*s){const uint8_t*p=glyph(*s++);for(int a=0;a<5;a++)for(int b=0;b<7;b++)if(p[a]&(1<<b))rect(x+a*z,y+b*z,z,z,c);x+=6*z;}}static int tw(const char*s,int z){return(int)strlen(s)*6*z-z;}static void tc(int y,const char*s,int z,uint16_t c){text((W-tw(s,z))/2,y,s,z,c);}static void clear(uint16_t c){for(int i=0;i<W*H;i++)frame[i]=c;}static void show(void){ESP_ERROR_CHECK(esp_lcd_panel_draw_bitmap(panel,0,0,W,H,frame));}
static void dots(int page,uint16_t a,uint16_t d){int total=PAGE_COUNT*8+(PAGE_COUNT-1)*8,start=(W-total)/2;for(int i=0;i<PAGE_COUNT;i++)rect(start+i*16,224,8,8,i==page?a:d);}static void button(int x,int y,int w,int h,const char*s,bool on){uint16_t cy=rgb(35,220,220),dim=rgb(30,48,60),wh=rgb(240,245,250);rect(x,y,w,h,on?cy:dim);text(x+(w-tw(s,2))/2,y+(h-14)/2,s,2,on?rgb(4,12,18):wh);}
static void logo_title(int y,int phase){uint16_t wh=rgb(240,245,250),pal[5]={rgb(30,120,255),rgb(175,55,255),rgb(255,35,150),rgb(255,120,25),rgb(45,225,120)};int z=4,x=(W-tw("PRISMA-PI",z))/2;text(x,y,"PRISMA",z,wh);const char*f="-PI";for(int i=0;f[i];i++){char o[2]={f[i],0};text(x+36*z+i*6*z,y,o,z,pal[(i+phase)%5]);}}
static void home(int phase){uint16_t bg=rgb(4,7,12),wh=rgb(240,245,250),cy=rgb(35,220,220),dim=rgb(45,60,75);clear(bg);logo_title(52,phase);tc(112,"SENSOR",3,wh);dots(0,cy,dim);show();}
static void audio(void){uint16_t bg=rgb(4,7,12),wh=rgb(240,245,250),cy=rgb(35,220,220),dim=rgb(45,60,75);prisma_sensor_audio_state_t s;prisma_sensor_audio_get_state(&s);char b[32];clear(bg);tc(15,"SENSOR AUDIO",2,cy);tc(40,s.face_down?"FACE DOWN MUTE":(s.enabled?"PLAYING":"STOPPED"),2,s.enabled&&!s.face_down?cy:wh);button(15,72,98,38,"PLAY",s.enabled);button(127,72,98,38,"STOP",!s.enabled);snprintf(b,sizeof(b),"%s  %.2f HZ",s.note_name,s.pitch_hz);tc(126,b,2,wh);snprintf(b,sizeof(b),"VOL %d",s.volume);tc(153,b,2,wh);button(24,181,70,30,"-",false);button(146,181,70,30,"+",false);dots(1,cy,dim);show();}
static void music(void){uint16_t bg=rgb(4,7,12),wh=rgb(240,245,250),cy=rgb(35,220,220),dim=rgb(45,60,75);prisma_sensor_audio_state_t s;prisma_sensor_audio_get_state(&s);char b[40];clear(bg);tc(10,"MUSICAL SCALE",2,cy);snprintf(b,sizeof(b),"ROOT %s",prisma_sensor_audio_root_name(s.root));tc(37,b,2,wh);button(18,61,55,30,"-",false);button(167,61,55,30,"+",false);tc(103,prisma_sensor_audio_scale_name(s.scale),2,cy);button(20,125,200,30,"NEXT SCALE",false);tc(166,prisma_sensor_audio_waveform_name(s.waveform),2,wh);button(20,188,200,28,"NEXT WAVE",false);dots(2,cy,dim);show();}
static void axes(void){uint16_t bg=rgb(4,7,12),wh=rgb(240,245,250),cy=rgb(35,220,220),dim=rgb(45,60,75);prisma_sensor_audio_state_t s;prisma_sensor_audio_get_state(&s);char b[32];clear(bg);tc(14,"ORIENTATION",2,cy);snprintf(b,sizeof(b),"X %+.1f",s.angle_x);text(18,52,b,2,wh);snprintf(b,sizeof(b),"Y %+.1f",s.angle_y);text(18,92,b,2,wh);snprintf(b,sizeof(b),"Z %.1f",s.angle_z);text(18,132,b,2,wh);snprintf(b,sizeof(b),"NOTE %s",s.note_name);text(125,52,b,2,cy);snprintf(b,sizeof(b),"HARM %d/5",s.voices);text(125,92,b,2,cy);text(125,132,s.face_down?"MUTE":"ON",2,cy);tc(180,"X QUANTIZED",2,wh);dots(3,cy,dim);show();}
static void gyro(void){uint16_t bg=rgb(4,7,12),wh=rgb(240,245,250),cy=rgb(35,220,220),dim=rgb(45,60,75);prisma_imu_data_t d;char b[32];clear(bg);tc(14,"GYROSCOPE",2,cy);if(prisma_sensors_imu_ready()&&prisma_sensors_read_imu(&d)){snprintf(b,sizeof(b),"X %+6d",(int)d.gyr_x);text(28,58,b,3,wh);snprintf(b,sizeof(b),"Y %+6d",(int)d.gyr_y);text(28,103,b,3,wh);snprintf(b,sizeof(b),"Z %+6d",(int)d.gyr_z);text(28,148,b,3,wh);}else tc(100,"NO SENSOR",2,wh);dots(4,cy,dim);show();}
static void speaker(void){uint16_t bg=rgb(4,7,12),wh=rgb(240,245,250),cy=rgb(35,220,220),dim=rgb(45,60,75);prisma_sensor_audio_state_t s;prisma_sensor_audio_get_state(&s);char b[32];clear(bg);tc(16,"SPEAKER",3,cy);tc(57,s.speaker_enabled?"OUTPUT ON":"OUTPUT OFF",2,wh);button(25,91,190,48,s.speaker_enabled?"TURN OFF":"TURN ON",s.speaker_enabled);snprintf(b,sizeof(b),"NOTE %s",s.note_name);tc(158,b,2,wh);snprintf(b,sizeof(b),"%.2f HZ",s.pitch_hz);tc(184,b,2,cy);dots(5,cy,dim);show();}
static void glitch(uint16_t x,uint16_t y){uint16_t pal[5]={rgb(30,120,255),rgb(175,55,255),rgb(255,35,150),rgb(255,120,25),rgb(45,225,120)};for(int i=0;i<9;i++){int dx=((i*17+glitch_count*11)%55)-27,dy=((i*23+glitch_count*7)%55)-27,sz=4+((i+glitch_count)%4)*3;rect((int)x+dx,(int)y+dy,sz,sz,pal[(i+glitch_count)%5]);}glitch_count++;show();}
static void draw_page(int p,int phase){if(p==0)home(phase);else if(p==1)audio();else if(p==2)music();else if(p==3)axes();else if(p==4)gyro();else speaker();}
static void tap_page(int p,uint16_t x,uint16_t y){prisma_sensor_audio_state_t s;prisma_sensor_audio_get_state(&s);if(p==1){if(y>=72&&y<=110)prisma_sensor_audio_set_enabled(x<120);else if(y>=176&&y<=216){int v=s.volume+(x<120?-10:10);if(v<0)v=0;if(v>100)v=100;prisma_sensor_audio_set_volume(v);}audio();}else if(p==2){if(y>=58&&y<=95){int r=(s.root+(x<120?11:1))%12;prisma_sensor_audio_set_root(r);}else if(y>=120&&y<=160)prisma_sensor_audio_set_scale((prisma_scale_t)(((int)s.scale+1)%PRISMA_SCALE_COUNT));else if(y>=180&&y<=220)prisma_sensor_audio_set_waveform((prisma_waveform_t)(((int)s.waveform+1)%PRISMA_WAVE_COUNT));music();}else if(p==5){if(y>=82&&y<=150)prisma_sensor_audio_set_speaker(!s.speaker_enabled);speaker();}}
void app_main(void){prisma_power_init();prisma_storage_init();gpio_config_t bl={.pin_bit_mask=1ULL<<LCD_PIN_BL,.mode=GPIO_MODE_OUTPUT};ESP_ERROR_CHECK(gpio_config(&bl));gpio_set_level(LCD_PIN_BL,0);spi_bus_config_t bus={.sclk_io_num=LCD_PIN_SCLK,.mosi_io_num=LCD_PIN_MOSI,.miso_io_num=-1,.quadwp_io_num=-1,.quadhd_io_num=-1,.max_transfer_sz=W*40*2};ESP_ERROR_CHECK(spi_bus_initialize(LCD_HOST,&bus,SPI_DMA_CH_AUTO));esp_lcd_panel_io_handle_t io=NULL;esp_lcd_panel_io_spi_config_t ioc={.dc_gpio_num=LCD_PIN_DC,.cs_gpio_num=LCD_PIN_CS,.pclk_hz=40000000,.lcd_cmd_bits=8,.lcd_param_bits=8,.spi_mode=0,.trans_queue_depth=10};ESP_ERROR_CHECK(esp_lcd_new_panel_io_spi((esp_lcd_spi_bus_handle_t)LCD_HOST,&ioc,&io));esp_lcd_panel_dev_config_t pc={.reset_gpio_num=LCD_PIN_RST,.rgb_ele_order=LCD_RGB_ELEMENT_ORDER_RGB,.bits_per_pixel=16};ESP_ERROR_CHECK(esp_lcd_new_panel_st7789(io,&pc,&panel));ESP_ERROR_CHECK(esp_lcd_panel_reset(panel));ESP_ERROR_CHECK(esp_lcd_panel_init(panel));ESP_ERROR_CHECK(esp_lcd_panel_invert_color(panel,true));ESP_ERROR_CHECK(esp_lcd_panel_disp_on_off(panel,true));int phase=0,page=0;draw_page(0,phase);gpio_set_level(LCD_PIN_BL,1);bool touch=prisma_touch_init();ESP_LOGI(TAG,"TOUCH: %s",touch?"READY":"FAILED");if(touch)ESP_LOGI(TAG,"SENSOR AUDIO: %s",esp_err_to_name(prisma_sensor_audio_start()));prisma_wifi_start();uint16_t x=0,y=0,startx=0,starty=0;bool down=false;int miss=0,anim=0,home_cooldown=0,refresh=0;while(1){if(home_cooldown>0)home_cooldown--;bool touched=touch&&prisma_touch_read(&x,&y);if(touched){miss=0;if(!down){startx=x;starty=y;down=true;}else{int dx=(int)x-(int)startx;if(dx<-SWIPE_THRESHOLD){if(page<PAGE_COUNT-1)page++;glitch_count=0;draw_page(page,phase);home_cooldown=HOME_COOLDOWN_TICKS;down=false;}else if(dx>SWIPE_THRESHOLD){if(page>0)page--;glitch_count=0;draw_page(page,phase);home_cooldown=HOME_COOLDOWN_TICKS;down=false;}}}else if(down&&++miss>4){if(page==0&&home_cooldown==0)glitch(startx,starty);else tap_page(page,startx,starty);down=false;miss=0;}if(page==0&&glitch_count==0&&++anim>=6){anim=0;phase=(phase+1)%5;draw_page(0,phase);}if(page>0&&++refresh>=10){refresh=0;draw_page(page,phase);}vTaskDelay(pdMS_TO_TICKS(20));}}
